using System;
using System.Linq;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.UI;
using TMPro;
using CelestialMaker.Core;
using BreakInfinity;
namespace CelestialMaker.EditorTools {
 public static partial class ObservatoryBatch {
  static void ScrollPurchaseIntoView(Button button){var sc=button.GetComponentInParent<ScrollRect>();if(!sc||!sc.content)return;Settle();var center=sc.viewport.InverseTransformPoint(button.transform.position);var position=sc.content.anchoredPosition;position.y=Mathf.Clamp(position.y+sc.viewport.rect.center.y-center.y,0,Mathf.Max(0,sc.content.rect.height-sc.viewport.rect.height));sc.content.anchoredPosition=position;Canvas.ForceUpdateCanvases();}
  static void PurchaseChecks(int width,int height){
   Check("Purchase bars follow real funding and prerequisites / "+width+"x"+height,()=>{
    Fixture(false,1,false,width,height);Set("page","Research");Call("ShowPc");Settle();var b=Button("Acquire r0");ScrollPurchaseIntoView(b);var track=(RectTransform)b.transform.Find("Purchase progress");var fill=(RectTransform)track.Find("Purchase funding");Require(Math.Abs(track.rect.height-3)<.01&&track.GetComponent<LayoutElement>().ignoreLayout&&!fill.GetComponent<Image>().raycastTarget,"Bar layout or hit testing");
    session.Sim.S.resources[0]=new BigDouble(100);Call("PresentPc");Require(Math.Abs(fill.anchorMax.x-.5f)<.001&&!b.interactable&&fill.GetComponent<Image>().color.r>.9f,"Partial funding must be yellow");session.Sim.S.resources[0]=new BigDouble(200);Call("PresentPc");Require(b.interactable&&fill.GetComponent<Image>().color.g>.8f&&fill.GetComponent<Image>().color.r<.3f,"Exact funds must be green");session.Sim.S.offlineRemaining=1;Call("PresentPc");Require(!b.interactable&&fill.GetComponent<Image>().color.r>.9f,"Catch-up cannot permit purchases");session.Sim.S.offlineRemaining=0;
    session.Sim.S.resources[0]=new BigDouble(600);ScrollPurchaseIntoView(Button("Acquire r1"));Call("PresentPc");var locked=Button("Acquire r1").transform.Find("Purchase progress/Purchase funding").GetComponent<Image>();Require(locked.color.r>.9f&&!Button("Acquire r1").interactable,"Currency cannot bypass prerequisites");Click("Acquire r0");Require(!Button("Acquire r0").transform.Find("Purchase progress").gameObject.activeSelf,"Purchased bars must disappear");
    Fixture(false,1,false,width,height);var price=session.Sim.Cost(0);session.Sim.S.resources[0]=price*.5;Call("PresentPc");var buy=Button("Buy process 0");ScrollPurchaseIntoView(buy);Call("PresentPc");var funded=(RectTransform)buy.transform.Find("Purchase progress/Purchase funding");Require(Math.Abs(funded.anchorMax.x-.5)<.001&&!buy.interactable,"Process half-funded");session.Sim.S.resources[0]=price;session.Sim.S.reserves[0]=price;Call("PresentPc");Require(funded.anchorMax.x==0&&!buy.interactable,"Protected stock must not fund buildings");session.Sim.S.reserves[0]=BigDouble.Zero;Call("PresentPc");Require(buy.interactable&&funded.anchorMax.x==1,"Next unit exact purchase");Geometry("purchase bars");
   });
   Check("Modal purchase bars update and release bindings / "+width+"x"+height,()=>{Fixture(false,1,false,width,height);session.Sim.S.resources[0]=new BigDouble(1000);Set("page","Research");Call("ShowPc");int before=Get<System.Collections.IList>("pcLive").Count;Call("ResearchComparisonPc",GameSession.Content.research[0]);session.Sim.S.resources[0]=new BigDouble(100);var acquire=Button("Acquire research");ScrollPurchaseIntoView(acquire);Call("PresentPc");Require(!acquire.interactable&&Math.Abs(((RectTransform)acquire.transform.Find("Purchase progress/Purchase funding")).anchorMax.x-.5)<.001,"Dialog bar stalled");Call("ClosePcModal");Require(Get<System.Collections.IList>("pcLive").Count==before,"Dialog live bindings leaked");});
  }
  static void ReadabilityChecks(){
   PurchaseChecks(1920,1080);PurchaseChecks(960,720);
   OnboardingChecks(1920,1080);OnboardingChecks(960,720);
   Check("Research rows are compact and explain exact missing resource",()=>{Fixture(false,1,false,1920,1080);Set("page","Research");Call("ShowPc");Settle();Require(ui.GetComponentsInChildren<TMP_Text>().Any(t=>t.text.Contains("Need 190 more Energy")),"Missing resource reason");var rows=ui.GetComponentsInChildren<RectTransform>().Where(t=>t.name.StartsWith("Research row ")).ToArray();Require(rows.Length>1&&rows[0].rect.height<180,"Not a compact research row");Require(rows[1].GetComponentsInChildren<TMP_Text>().Any(t=>t.text.Contains("Research Quantum memory 1 first")),"Missing prerequisite reason");});
   Check("Research filter has selected fill and preserves independent upgrade choice",()=>{Fixture(false,1,false,1920,1080);Set("page","Research");Call("ShowPc");Click("Research filter 2");var chosen=Button("Research filter 2").GetComponent<CosmicPanel>();Require(chosen.edge==2&&chosen.color!=Button("Research filter 0").GetComponent<CosmicPanel>().color,"No selected appearance");Set("page","Upgrades");Call("ShowPc");Require(session.CurrentSettings.observatory.researchFilter==2&&session.CurrentSettings.observatory.upgradeFilter==0,"Filters coupled");});
   Check("Research search and favorite result filtering",()=>{Fixture(false,1,false,1920,1080);var p=session.CurrentSettings.observatory;p.researchSearch="Quantum memory 2";p.favorites.Add(GameSession.Content.research[1].id);p.researchFavorites=true;Set("page","Research");Call("ShowPc");Settle();Require(ui.GetComponentsInChildren<RectTransform>().Count(t=>t.name.StartsWith("Research row "))==1,"Search did not narrow list");p.researchSearch="no such research";Call("ShowPc");Require(Button("Clear research filters"),"No empty state recovery");Click("Clear research filters");Require(p.researchSearch==""&&!p.researchFavorites,"Clear filters incomplete");});
   Check("Search palette opens a route and persists favorites",()=>{Fixture(false,1,false,1920,1080);Call("SearchPalettePc",false);Set("pcPaletteQuery","Quantum memory 1");Call("PopulatePalettePc");Settle();Click("Add favorite");Require(session.CurrentSettings.observatory.favorites.Count==1,"Favorite not stored");Click("Research / Quantum memory 1");Require(Get<string>("page")=="Research"&&Get<string>("pcExpandedResearch")==GameSession.Content.research[0].id,"Search navigation failed");});
   Check("Pinned goal readiness notification is emitted once and can be disabled",()=>{Fixture(false,1,false,1920,1080);var p=session.CurrentSettings.observatory;p.goal=GameSession.Content.research[0].id;Set("pcGoalNotice","");Call("CheckPinnedGoalPc");session.Sim.S.resources[0]=new BigDouble(1000);Call("CheckPinnedGoalPc");Require(Get<string>("pcToastText").StartsWith("Goal ready"),"No readiness notice");Set("pcToastText","sentinel");Call("CheckPinnedGoalPc");Require(Get<string>("pcToastText")=="sentinel","Repeated notice");p.readyNotifications=false;session.Sim.Purchase(GameSession.Content.research[0]);Call("CheckPinnedGoalPc");Require(Get<string>("pcToastText")=="sentinel","Disabled notifications emitted");});
   Check("Category labels and all button states keep readable contrast",()=>{foreach(bool light in new[]{false,true}){Fixture(true,1,light,1920,1080);var colors=new HashSet<Color>();foreach(var b in Get<Dictionary<string,Button>>("pcTabs").Values){colors.Add(b.GetComponentInChildren<ObservatoryCategoryIcon>().color);foreach(string state in new[]{"Normal","Highlighted","Selected","Disabled"}){ButtonState((ObservatoryButton)b,state);float a=Luminance(b.GetComponentInChildren<TMP_Text>().color),bg=Luminance(b.GetComponent<CosmicPanel>().color);Require((Mathf.Max(a,bg)+.05f)/(Mathf.Min(a,bg)+.05f)>=4.5f,"Contrast failed");}}Require(colors.Count==6,"Category accents not distinct");}});
   Check("Preferences and queue survive Unity JSON and old save defaults",()=>{Fixture(false,1,false,1920,1080);session.Sim.QueueResearch(GameSession.Content.research[1].id);session.CurrentSettings.observatory.favorites.Add("page:Research");session.CurrentSettings.observatory.researchFilter=2;var state=SaveStore.Parse(JsonUtility.ToJson(session.Sim.S));Require(state.researchPlan.queue.Count==2&&state.settings.observatory.researchFilter==2&&state.settings.observatory.favorites.Contains("page:Research"),"Unity lost planning fields");var old=new State{researchPlan=null};old.settings.observatory=null;var migrated=SaveStore.Parse(JsonUtility.ToJson(old));Require(migrated.researchPlan!=null&&migrated.settings.observatory!=null,"Old optional fields not migrated");});
   foreach(float scale in new[]{1f,2f})foreach(bool light in new[]{false,true}){
    string key=scale+"/"+light;
    Check("Expanded research and pinned goal geometry "+key,()=>{Fixture(false,scale,light,1280,720);session.Sim.S.resources[0]=new BigDouble(10000);session.CurrentSettings.observatory.goal=GameSession.Content.research[0].id;Set("page","Research");Set("pcExpandedResearch",GameSession.Content.research[0].id);Call("ShowPc");Settle();Geometry("expanded research");});
    Check("Search plan comparison and navigation dialogs geometry "+key,()=>{Fixture(false,scale,light,1280,720);session.Sim.S.resources[0]=new BigDouble(10000);session.Sim.QueueResearch(GameSession.Content.research[1].id);Call("ResearchPlanPc");Settle();Geometry("plan");Call("ClosePcModal");Call("SearchPalettePc",false);Settle();Geometry("search");Call("ClosePcModal");Call("ResearchFilterDialogPc",true);Settle();Geometry("compact filters");var query=Get<RectTransform>("pcModal").GetComponentInChildren<TMP_InputField>();query.text="Quantum";Click("Cancel");Require(session.CurrentSettings.observatory.researchSearch=="","Cancelled filters leaked");Call("SectionViewsPc");Settle();Geometry("compact views");Call("ClosePcModal");Call("ResearchComparisonPc",GameSession.Content.research[0]);Settle();Geometry("comparison");Call("ClosePcModal");Call("NavigationDrawerPc");Settle();Geometry("drawer");Require(!Button("Development")&&Button("Production"),"Locked navigation leaked");Click("Production");Require(Get<string>("page")=="Production","Drawer selection failed");});
   }
   Check("Narrow window expands workspace and hides side panels",()=>{Fixture(false,1,false,960,720);Require(Get<bool>("pcCompactNav")&&Get<RectTransform>("pcInspector")==null&&Button("Menu / Find"),"Adaptive navigation missing");Require(Get<RectTransform>("body").rect.width>900,"Workspace still reserves rail");Set("page","Research");Call("ShowPc");Settle();Geometry("960 wide");});
  }
  static void OnboardingChecks(int width,int height){
   Check("Purchased research and upgrades move behind pending rows / "+width,()=>{Fixture(false,1,false,width,height);session.Sim.S.resources[0]=new BigDouble(10000);session.Sim.Purchase(GameSession.Content.research[0]);Set("page","Research");Call("ShowPc");Settle();var rows=ui.GetComponentsInChildren<RectTransform>().Where(t=>t.name.StartsWith("Research row ")).ToArray();Require(rows[0].name=="Research row r1"&&rows.Last().name=="Research row r0","Purchased research is ahead of pending work");session.Sim.Purchase(GameSession.Content.research[1]);Call("RefreshCompletedListsPc");rows=ui.GetComponentsInChildren<RectTransform>().Where(t=>t.name.StartsWith("Research row ")).ToArray();Require(rows[0].name=="Research row r2"&&rows.Last().name=="Research row r1","Background purchases did not reorder");session.Sim.Purchase(GameSession.Content.upgrades[0]);Set("page","Upgrades");Call("ShowPc");rows=ui.GetComponentsInChildren<RectTransform>().Where(t=>t.name.StartsWith("Research row ")).ToArray();Require(rows[0].name=="Research row u1"&&rows.Last().name=="Research row u0","Purchased upgrade at top");});
   Check("Only true maxed processes move to the end / "+width,()=>{Fixture(false,1,false,width,height);session.Sim.S.owned[0]=100;Call("ShowPc");Require(ui.GetComponentsInChildren<RectTransform>().First(t=>t.name.StartsWith("Process row ")).name=="Process row 0","Milestone treated as cap");session.Sim.S.owned[0]=1000000000;Call("ShowPc");Settle();var rows=ui.GetComponentsInChildren<RectTransform>().Where(t=>t.name.StartsWith("Process row ")).ToArray();Require(rows.Last().name=="Process row 0"&&!Button("Buy process 0").interactable&&Button("Buy process 0").GetComponentInChildren<TMP_Text>().text=="Maxed","Ownership cap not distinguished");});
   Check("First steps advance from real purchases without reset or grants / "+width,()=>{Fixture(false,1,false,width,height);session.CurrentSettings.tutorial=true;Call("ShowPc");Settle();Require(Button("First steps action"),"Guide not visible");Require((string)typeof(GameUI).GetMethod("NextDecisionPc",Private).Invoke(ui,null)==session.Sim.FirstSteps().title+".","Conflicting next decision");Set("page","Overview");Call("ShowPc");Require(!ui.GetComponentsInChildren<RectTransform>().Any(t=>t.name=="Next decision"),"Duplicate next-action card");session.Sim.S.resources[0]=new BigDouble(1000);Call("PresentPc");Click("First steps action");Click("First steps action");Require(session.Sim.FirstSteps().step==1,"Dynamos did not advance guide");Click("First steps action");Click("First steps action");Click("First steps action");Require(session.Sim.FirstSteps().step==4&&session.Sim.S.resets[0]==0&&!session.Sim.AnyAutobuyer,"Guide performed unrequested reset/unlock");Geometry("starter guide");Call("FirstStepsHelpPc");Settle();Geometry("first steps explanation");Call("ClosePcModal");Click("Hide first steps");Require(!session.CurrentSettings.tutorial&&!Button("First steps action"),"Hide preference not respected");Set("page","Overview");Call("ShowPc");Click("Show tutorial");Require(Button("First steps action"),"Reopen unavailable");});
   foreach(float textScale in new[]{1f,1.25f,2f})Check("Starter guide is readable at "+textScale+" / "+width,()=>{Fixture(false,textScale,false,width,height);session.CurrentSettings.tutorial=true;foreach(string route in new[]{"Overview","Production"}){Set("page",route);Call("ShowPc");Settle();Geometry("first steps "+route);}Call("FirstStepsHelpPc");Settle();Geometry("starter explanation");Call("ClosePcModal");});
  }
 }
}
